'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict');
const engine=fs.readFileSync('docs/scifi-ui/scripts/formatx-mag-genesis-three-r1280.js','utf8');
const birth=fs.readFileSync('docs/scifi-ui/scripts/formatx-mag-birth-live-r533.js','utf8');
assert.doesNotThrow(()=>new Function(engine));assert.doesNotThrow(()=>new Function(birth));
const a=engine.indexOf('    studioPixelRatio('),b=engine.indexOf('    resize(){',a);
const c=engine.indexOf('    updateStudioCadence('),d=engine.indexOf('    targetWorld(){',c);
assert.ok(a>=0&&b>a&&c>=0&&d>c);
const make=new Function('navigator','document','devicePixelRatio','return ({'+engine.slice(a,b)+','+engine.slice(c,d)+'})');
const e=Object.assign(make({webdriver:false},{hidden:false},1),{studioHardware:true,mobileRender:false,maxRenderSize:8192,width:3840,height:2160,resize(){}});
assert.equal(e.studioPixelRatio(3840,2160,1),1);
let t=0;e.updateStudioCadence(t);
for(let i=0;i<4;i++)e.updateStudioCadence(t+=33);
assert.equal(e.studioScale,.88);
for(let i=0;i<80;i++)e.updateStudioCadence(t+=33);
assert.equal(e.studioScale,.5);
assert.equal(e.studioPixelRatio(3840,2160,1),.5);
for(let i=0;i<45;i++)e.updateStudioCadence(t+=16.666);
assert.ok(e.studioScale>.5);
const cadence=birth.match(/const particleCadence=([^;]+);/)[1];
const gate=new Function('softwareFallbackActive','return '+cadence);
assert.equal(gate(false),0);assert.equal(gate(true),125);
console.log('R2327 display cadence and UHD/FHD adaptive rendering: PASS');
